            conn.commit()
            return {'request_id':request_id,'replayed':False,'retries':attempt}
        except pymysql.OperationalError as exc:
            conn.rollback()
            if exc.args[0] in (1213,1205) and attempt<3:
                time.sleep(.02*(attempt+1))
                continue
            raise
