    return _post(conn,request_id,src,dst,amount,after_first_lock=after_first_lock)

def reverse(conn,request_id,original_id):
    rows=query(conn,'SELECT src,dst,amount,original_id FROM requests WHERE id=%s',(original_id,))
    if not rows or rows[0][3] is not None: raise ValueError('normal original transfer required')
    src,dst,amount,_=rows[0]
    return _post(conn,request_id,dst,src,amount,original_id=original_id)

